let audioPickTimer=null;if(typeof window!=='undefined')window.careAudioPicked=payload=>{try{if(audioPickTimer){clearTimeout(audioPickTimer);audioPickTimer=null;}const d=typeof payload==='string'?JSON.parse(payload):payload;if(!d||!d.file)return;state.settings.customTone=d.file;state.settings.customToneName=d.name||'Custom audio';state.settings.toneUri='';state.settings.toneName='';save();render();toast('Custom alarm sound saved.')}catch{toast('That audio file could not be saved.')}};
