function routines(){return `<div class="toolbar"><button class="ghost" id="group-add">Create reminder group</button></div>${state.routines.map(r=>`<section class="card"><div class="topline"><span class="care-thumb">${icon(r.type)}</span><div><h2>${esc(r.name)}</h2><small>${labels[r.type]||'Medicine'} · ${r.archived?'Archived':r.times.length?r.times.map(fmt).map(esc).join(', '):'Any time'}</small></div></div>${r.type!=='todo'&&streakInfo(state,r.id).current>0?`<span class="streak-pill">${icon('flame')}${streakInfo(state,r.id).current}-day streak</span>`: ''}<div class="quiet-actions"><button class="link" data-detail="${r.id}">Details & history</button><button class="link" data-edit="${r.id}">Edit</button><button class="link danger" data-routine-delete="${r.id}">Delete</button></div></section>`).join('')||'<p class="empty-copy">Your routines will live here.</p>'}${state.groups.map(g=>`<section class="card"><h2>${icon('group')}${esc(g.name)}</h2><p>${g.members.map(m=>esc(state.routines.find(r=>r.id===m.routineId)?.name||'Archived item')+' · '+esc(fmt(m.time))).join('<br>')}</p><button class="link" data-group="${g.id}">Edit group</button></section>`).join('')}<button class="primary list-add" id="add">Add routine or to-do</button>`}
