function donateSection(){return `<section class="card donate-section"><h2>${icon('heart')}Donate to the developer</h2><img class="donate-art" src="art/art-donate.svg" alt="A friendly capsule character holding a heart" width="160" height="90"><button type="button" class="qr-button" data-donate aria-label="Tap to pay with any UPI app"><span class="btn-label"><img class="donate-qr" src="donate-qr.png" alt="QR code — scan to pay with any UPI app" width="240" height="240"></span></button><p>Scan to pay with any UPI app · or tap the code to pay.</p><button type="button" class="primary" data-donate>Click to pay</button><p class="upi-row">UPI ID: <strong>${DONATE_UPI_ID}</strong> <button type="button" class="link" id="copy-upi-settings">Copy</button></p><p>Your donation helps keep Remibuds running and ad-free.</p></section>`}
function launchLine(d){const posted=d.shownAt?('Notification posted '+new Date(d.shownAt).toLocaleDateString()+' · '+fmt(new Date(d.shownAt).toISOString())+(d.shownRing?' · ringing':'')):'No reminder notification recorded';return posted+' · App opened via notification: '+(d.openedViaNotification?'Yes':'No')+' · Reminder card reached: '+(d.cardReached?'Yes':'No')}
function settings(st){const zone=Intl.DateTimeFormat().resolvedOptions().timeZone,zoneChanged=native()?!!st.timezoneChanged:state.settings.zone!==zone;let crash=null;if(native()&&!QA){try{crash=JSON.parse(native().crashReport()||'{"exists":false}')}catch{crash=null}}if(crash?.exists)lastCrashBody=crash.body||'';let donateDiag=null,launchDiag=null;if(native()&&!QA){try{donateDiag=JSON.parse(native().donateReport()||'{"exists":false}')}catch{donateDiag=null}try{launchDiag=JSON.parse(native().launchReport()||'{"exists":false}')}catch{launchDiag=null}}if(donateDiag?.exists)lastDonateBody=JSON.stringify(donateDiag,null,2);if(launchDiag?.exists)lastLaunchBody=JSON.stringify(launchDiag,null,2);return `${moreCard()}<section class="card"><h2>${icon('bell')}Phone reminders</h2><p class="status-line">${st.ready?'Phone scheduling is ready':state.settings.enabled?'Permissions need attention':'Reminders are off'}</p>${st.error?`<p class="notice">${esc(st.error)}</p>`:''}<div class="actions"><button class="primary" id="enable">Enable reminders</button><button class="ghost" id="disable">Turn off</button></div>${native()?`<div class="permission-list">${[['notifications','Notifications',st.permission],['channel','Sound & banners',st.channel==='blocked'?'blocked':(!st.sound||!st.headsUp)?'quiet':st.channel],['exact','Precise reminder timing',st.exact],['battery','Battery / background',st.battery],['lockscreen','Lock-screen display',st.lockscreen],['fullscreen','Full-screen display',st.fullscreen]].map(([key,label,value])=>`<div class="permission-row"><div><strong>${label}</strong><small>${esc(({granted:'Allowed',denied:'Blocked · allow in phone settings',default:'Not requested',allowed:'Allowed',blocked:'Blocked',quiet:'Quiet channel · check sound and banners',unrestricted:'Battery exemption allowed',optimized:'Battery optimization on · delays possible',hidden:'Hidden',unknown:'Check phone settings','not-required':'Not required'})[value]||'Check phone settings')}</small></div><button class="link" data-phone="${key}">Settings</button></div>`).join('')}</div><p class="fineprint">Android and Samsung settings control sound, banners and lock-screen display. Do Not Disturb, battery limits and force-stop may prevent alerts. No app can alert while the phone is fully powered off.</p>`:'<p>Phone reminders are available in the Android app. Your records stay on this device.</p>'}</section><section class="card early-card"><div class="topline"><span class="care-thumb">${icon('bell')}</span><div><h2>Early alerts</h2><small>A quiet heads-up before each reminder</small></div><span class="pill ${state.settings.earlyAlerts!==false?'':'pill-off'}">${state.settings.earlyAlerts!==false?'On':'Off'}</span></div><div class="early-preview"><small class="early-preview-label">Example notification</small><div class="early-notif"><span class="early-notif-icon">${icon('bell')}</span><div><strong>Evening walk in 1 hour</strong><small>Due at 6:00 PM \u00b7 Remibuds</small></div></div></div><p class="early-detail">Always 1 day, 1 hour and 30 minutes before it is due, plus one extra heads-up at a random time up to a day before. Plays your phone's default notification sound \u2014 it does not ring. Works even if gentle nudges are off.</p><label class="switch-row"><span class="switch"><input type="checkbox" data-early-toggle ${state.settings.earlyAlerts!==false?'checked':''} aria-label="Early alerts before reminders"><span class="switch-track"><span class="switch-thumb"></span></span></span><span>${state.settings.earlyAlerts!==false?'On':'Off'}</span></label><button type="button" class="ghost" data-early-test>${icon('bell')} Test your notification</button></section>${soundCard(st)}<section class="card"><h2>Make it yours</h2><label>Time format</label><div class="chips" role="group" aria-label="Time format">${['12','24'].map(v=>`<button class="${(state.settings.timeFormat||'12')===v?'selected':''}" data-format="${v}" aria-pressed="${(state.settings.timeFormat||'12')===v}">${v==='12'?'12-hour · AM / PM':'24-hour'}</button>`).join('')}</div><label>Snooze length</label><div class="chips" role="group" aria-label="Snooze length">${[5,10,15,30,60].map(n=>`<button data-duration="${n}" class="${state.settings.snooze===n?'selected':''}" aria-pressed="${state.settings.snooze===n}">${n}m</button>`).join('')}</div>${zoneChanged?'<p class="notice">Timezone changed. Review your timing before reminders resume.</p><button id="zone-confirm" class="ghost">Use current timezone</button>':''}</section><section class="card"><h2>${icon('lock')}Your private records</h2><p>No account, sharing or automatic backup. Uninstalling or clearing app data can erase your records.</p><div class="actions"><button class="ghost" id="export">Export backup</button><button class="ghost" id="export-csv">Export history (CSV)</button><button class="ghost" id="restore">Restore backup</button></div><input type="file" id="import" accept="application/json" hidden><button class="link danger" id="delete">Delete all local data</button></section>${donateSection()}<section class="card"><h2>About ${NAME}</h2><p>Version ${VERSION} · build ${CODE}</p><small>A private place for daily routines, prescribed care, and things to remember. Medicine records are your reports, not proof of ingestion.</small><button class="menu-row" data-subpage="logs"><span class="menu-icon">${icon('info')}</span><span class="btn-label"><strong>Logs &amp; errors</strong><small>${crash?.exists?'Last problem report saved · tap to view':'No problem reports saved'}</small></span><span class="menu-chev">${icon('right')}</span></button></section>`}
function typePicker(type,family){return `<div class="type-tabs" role="radiogroup" aria-label="Routine type">${(family==='medicine'?medTypes:family==='activity'?activities:['todo']).map(t=>`<label class="type-option type-${t}"><input type="radio" name="type" value="${t}" ${t===type?'checked':''}><span>${icon(t)}<span>${labels[t]}</span></span></label>`).join('')}</div>`}
function timeRow(value='08:00'){const [h,m]=value.split(':').map(Number),is12=(state.settings.timeFormat||'12')==='12';return `<div class="time-row"><label><span class="sr-only">Hour</span><select class="time-hour" aria-label="Hour">${Array.from({length:is12?12:24},(_,i)=>is12?i+1:i).map(n=>`<option value="${n}" ${n===(is12?h%12||12:h)?'selected':''}>${is12?n:String(n).padStart(2,'0')}</option>`).join('')}</select></label><span class="time-colon">:</span><label><span class="sr-only">Minute</span><select class="time-minute" aria-label="Minute">${Array.from({length:60},(_,n)=>`<option value="${n}" ${n===m?'selected':''}>${String(n).padStart(2,'0')}</option>`).join('')}</select></label>${is12?`<label><span class="sr-only">AM or PM</span><select class="time-period" aria-label="AM or PM"><option value="AM" ${h<12?'selected':''}>AM</option><option value="PM" ${h>=12?'selected':''}>PM</option></select></label>`:''}<button type="button" class="icon-button remove-time" aria-label="Remove time">${icon('close')}</button></div>`}
function amountFields(type,value=''){if(['tablet','capsule','injection'].includes(type)&&value)value=String(parseFloat(value)||'');const unit=({tablet:'tablets',capsule:'capsules',liquid:'mL (as prescribed)',drops:'drops',injection:'injections',water:'amount (optional)'})[type];if(['gel','patch','todo','walk','outing','custom'].includes(type))return '';return `<label>Amount per occurrence (optional)<input name="amount" value="${esc(value)}" ${['tablet','capsule','injection'].includes(type)?'type="number" min="0" step="1"':'type="text"'} placeholder="${unit||'Your prescribed amount'}"></label><small>${isMed({type})?'Only enter your own prescription amount. Daily counts are separate occurrences.':'Optional, in your own words.'}</small>`}
function artPicker(selected,family='medicine'){const list=ART_CATEGORIES.filter(c=>(ART_GROUPS[family]||[]).includes(c.key));return `<div class="art-picker" role="radiogroup" aria-label="Routine illustration">${list.map(c=>`<label class="art-option"><input type="radio" name="art" value="${c.key}" ${c.key===selected?'checked':''}><img src="${artSrc(c.key)}" alt="" width="120" height="68"><span>${c.label}</span></label>`).join('')}</div>`}
function firstFormTime(){const row=$('#time-list .time-row');if(!row)return '';try{return parseTime(row.querySelector('.time-hour').value,row.querySelector('.time-minute').value,row.querySelector('.time-period')?.value||'24')}catch{return ''}}
function edit(rid){let r=state.routines.find(x=>x.id===rid)||{id:id(),name:'',type:'tablet',times:['08:00'],days:[0,1,2,3,4,5,6],start:'',notes:'',remind:true},family=r.type==='todo'?'todo':activities.includes(r.type)?'activity':'medicine';modal(rid?'Edit routine':'Add to your day',`<form id="routine-form"><label>Name / reminder title<input name="name" required maxlength="100" value="${esc(r.name)}" placeholder="Your own name, in any language"></label><label>Kind<select name="family"><option value="medicine" ${family==='medicine'?'selected':''}>Medicine or prescribed care</option><option value="activity" ${family==='activity'?'selected':''}>Daily activity</option><option value="todo" ${family==='todo'?'selected':''}>One-time to-do</option></select></label><label>Illustration</label><div id="art-picker">${artPicker(artFor(r),family)}</div><small>Suggested from the name — tap a picture to change it, or leave the suggestion.</small><div id="type-picker">${typePicker(r.type,family)}</div><div id="amount-fields">${amountFields(r.type,r.amount)}</div><div id="todo-options" ${family!=='todo'?'hidden':''}><label>Due date<input name="dueDate" type="date" value="${r.dueDate||dayKey()}"></label><label class="checkbox-label"><input type="checkbox" id="untimed" ${!r.times.length?'checked':''}>No set time</label></div><div id="timed-fields" ${family==='todo'&&!r.times.length?'hidden':''}><label>Time${(state.settings.timeFormat||'12')==='12'?' · choose AM or PM':''}</label><div id="time-list">${(r.times.length?r.times:['08:00']).map(timeRow).join('')}</div><button type="button" class="link" id="time-add">Add another time</button><div id="todo-timing" ${family!=='todo'?'hidden':''}><label>Reminder timing<select name="dueMode"><option value="at" ${r.dueMode!=='before'?'selected':''}>At due time</option><option value="before" ${r.dueMode==='before'?'selected':''}>Before due time</option></select></label><label class="before-field" ${r.dueMode!=='before'?'hidden':''}>Minutes before<input name="beforeMinutes" type="number" min="1" max="1440" value="${r.beforeMinutes||15}"></label><label>Repeat until done<select name="repeatMinutes">${[[0,'Do not repeat'],[15,'Every 15 minutes'],[30,'Every 30 minutes'],[60,'Every hour'],[120,'Every 2 hours']].map(([v,t])=>`<option value="${v}" ${(r.repeatMinutes??15)===v?'selected':''}>${t}</option>`).join('')}</select></label><small>Repeated reminders apply only to this to-do, never to medicine.</small></div></div><div id="recurring-fields" ${family==='todo'?'hidden':''}><label>Days</label><div class="days">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((d,i)=>`<label><input type="checkbox" name="days" value="${i}" ${r.days.includes(i)?'checked':''}>${d}</label>`).join('')}</div><label>Treatment / routine started (optional)<input name="start" type="date" value="${r.start||''}"></label><small>Blank means not provided. It can be in the past.</small></div><label>Your notes (optional)<textarea name="notes" maxlength="2000">${esc(r.notes||'')}</textarea></label><label class="checkbox-label"><input type="checkbox" name="remind" ${r.remind!==false?'checked':''}>Remind me for timed occurrences</label><button class="primary form-submit" type="submit">Save ${rid?'changes':'routine'}</button>${rid?`<button class="link danger" type="button" id="archive">${r.archived?'Restore routine':'Archive routine'}</button><button class="link danger" type="button" id="routine-delete">Delete routine</button>`:''}</form>`);
const updateFamily=()=>{family=$('[name=family]').value;const t=family==='medicine'?'tablet':family==='activity'?'water':'todo';artManual=false;$('#type-picker').innerHTML=typePicker(t,family);$('#art-picker').innerHTML=artPicker(guessFromForm(),family);$('#amount-fields').innerHTML=amountFields(t);$('#todo-options').hidden=family!=='todo';$('#todo-timing').hidden=family!=='todo';$('#recurring-fields').hidden=family==='todo';$('#time-add').hidden=family==='todo';$('#timed-fields').hidden=family==='todo'&&$('#untimed').checked;refreshArt()};let artManual=!!r.art;const guessFromForm=()=>{try{return guessArtForFamily($('[name=name]').value,$('[name=type]:checked')?.value||r.type,firstFormTime(),family)}catch{return artFor(r)}};const refreshArt=()=>{if(artManual)return;const g=guessFromForm();if(!g)return;const radio=$(`#art-picker input[value="${g}"]`);if(radio)radio.checked=true};$('[name=name]').addEventListener('input',refreshArt);$('#art-picker').addEventListener('change',()=>{artManual=true});$('[name=family]').onchange=updateFamily;$('[name=dueMode]').onchange=()=>$('.before-field').hidden=$('[name=dueMode]').value!=='before';$('#type-picker').onchange=()=>{$('#amount-fields').innerHTML=amountFields($('[name=type]:checked').value);refreshArt()};$('#untimed').onchange=()=>$('#timed-fields').hidden=$('#untimed').checked;$('#time-list').onclick=e=>{const b=e.target.closest('.remove-time');if(b){if($('#time-list').children.length===1)return toast('Keep one time, or choose No set time for a to-do.');b.closest('.time-row').remove()}};$('#time-add').hidden=family==='todo';$('#time-add').onclick=()=>{$('#time-list').insertAdjacentHTML('beforeend',timeRow('20:00'));polishButtons($('#modal'))};$('#archive')?.addEventListener('click',()=>{updateRoutine(state,{...r,archived:!r.archived});save();$('#modal').close();render()});$('#routine-delete')?.addEventListener('click',()=>ask('Delete this routine?','This deletes the routine and its future reminders. Its history stays as a permanent log.',()=>{deleteRoutine(state,r.id);save();$('#modal').close();render();toast('Routine deleted. Its history stays as a permanent log.')}));$('#routine-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),todo=type==='todo',untimed=todo&&$('#untimed').checked;let times=untimed?[]:[...$('#time-list').children].map(row=>parseTime(row.querySelector('.time-hour').value,row.querySelector('.time-minute').value,row.querySelector('.time-period')?.value||'24'));times=[...new Set(times)].sort();const days=todo?[0,1,2,3,4,5,6]:f.getAll('days').map(Number);if(!days.length)return toast('Choose at least one day.');if(state.groups.some(g=>g.members.some(m=>m.routineId===r.id&&!times.includes(m.time))))return toast('Edit the group first before removing an assigned time.');const amount=f.get('amount')||'',unit=({tablet:' tablets',capsule:' capsules',injection:' injections'})[type]||'';const next={...r,name:String(f.get('name')).trim(),type,times,days,art:f.get('art')||artFor({name:String(f.get('name')).trim(),type,times}),amount:amount?String(amount)+(unit&&!String(amount).includes(unit.trim())?(parseFloat(amount)===1?unit.replace(/s$/,''):unit):''):'',start:todo?'':f.get('start'),notes:f.get('notes'),remind:f.has('remind'),dueDate:todo?f.get('dueDate'):undefined,dueMode:todo?f.get('dueMode'):'at',beforeMinutes:todo?+f.get('beforeMinutes'):0,repeatMinutes:todo?+f.get('repeatMinutes'):0,added:r.added||new Date().toISOString()};if(!next.name||todo&&!next.dueDate)return toast('Enter a name and due date.');const saved=updateRoutine(state,next);save();$('#modal').close();render();if(saved.scheduleFrom>dayKey())toast('Schedule changes start tomorrow because this medicine already has an entry today.')};}
function groupEdit(gid){const g=state.groups.find(x=>x.id===gid)||{id:id(),name:'',members:[]};modal('Shared reminder',`<form id="group-form"><label>Group title<input name="name" required maxlength="100" value="${esc(g.name)}"></label><p>Select existing scheduled times. Members at the same time share one reminder; no medicine schedule is changed.</p>${state.routines.filter(r=>!r.archived&&r.type!=='todo').map(r=>r.times.map(t=>`<label class="checkbox-label"><input type="checkbox" name="members" value="${r.id}|${t}" ${g.members.some(m=>m.routineId===r.id&&m.time===t)?'checked':''}>${esc(r.name)} · ${esc(fmt(t))}</label>`).join('')).join('')||'<p>Add timed routines first.</p>'}<button class="primary form-submit" type="submit">Save group</button>${gid?'<button type="button" class="link danger" id="group-delete">Remove group</button>':''}</form>`);$('#group-delete')?.addEventListener('click',()=>{state.groups=state.groups.filter(x=>x.id!==gid);save();$('#modal').close();render()});$('#group-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),members=f.getAll('members').map(v=>{const [routineId,time]=v.split('|');return{routineId,time}});if(!members.length)return toast('Select at least one occurrence.');if(state.groups.some(x=>x.id!==g.id&&x.members.some(m=>members.some(n=>m.routineId===n.routineId&&m.time===n.time))))return toast('An occurrence can share one group reminder. Edit its existing group first.');g.name=f.get('name').trim();if(!g.name)return toast('Enter a group title.');g.members=members;if(!gid)state.groups.push(g);save();$('#modal').close();render()};}
function detail(rid){if(rid.startsWith('group:')){const gid=rid.slice(6),g=state.groups.find(x=>x.id===gid),gm=g?.members[0],gr=gm&&state.routines.find(x=>x.id===gm.routineId);modal('Group details',`${gr?`<img class="detail-art" src="${esc(artSrc(artFor(gr)))}" alt="" aria-hidden="true">`:''}<p>Each member has its own record. Snoozing a member defers only that member. To share another time, select it explicitly in the group editor.</p><button id="group-edit-detail" class="primary">Edit shared reminder</button>`);$('#group-edit-detail').onclick=()=>groupEdit(gid);return}const r=state.routines.find(x=>x.id===rid);if(!r)return;const first=state.logs.filter(l=>l.routineId===rid&&!l.undone&&l.status==='recorded').sort((a,b)=>a.reported.localeCompare(b.reported))[0];modal(r.name,`<img class="detail-art" src="${esc(artSrc(artFor(r)))}" alt="" aria-hidden="true"><p><strong>${labels[r.type]||'Medicine'}</strong>${r.amount?' · '+esc(displayAmount(r.amount)):''}</p>${r.scheduleFrom>dayKey()?'<p class="notice">Schedule changes start '+esc(r.scheduleFrom)+'. Today’s existing medicine records keep their original times.</p>':''}<p>Started: ${esc(r.start||'Not provided')}</p><p>Added to app: ${r.added?esc(new Date(r.added).toLocaleDateString()):'Not provided'}</p><p>First recorded: ${first?esc(new Date(first.reported).toLocaleDateString())+' · '+esc(fmt(first.reported)):'None yet'}</p><p>${esc(r.notes)||'No notes provided.'}</p><p>${count(state,r.id,date)} recorded for ${esc(date)}.</p><div class="actions"><button class="primary" id="detail-history">View history</button><button class="ghost" data-edit="${r.id}" id="detail-edit">Edit</button><button class="link danger" id="detail-delete">Delete routine</button></div>${isMed(r)?'<p class="fineprint">Unsure what you took? Check your prescription and ask a pharmacist or clinician. No entry means not recorded.</p><button class="link" id="additional">Report a separate additional action</button>':''}`);$('#detail-history').onclick=()=>{$('#modal').close();page='History';filter=rid;render()};$('#detail-edit').onclick=()=>edit(rid);$('#detail-delete')?.addEventListener('click',()=>ask('Delete this routine?','This deletes the routine and its future reminders. Its history stays as a permanent log.',()=>{deleteRoutine(state,rid);save();$('#modal').close();render();toast('Routine deleted. Its history stays as a permanent log.')}));$('#additional')?.addEventListener('click',()=>reportExtra(r));}
function dateTimeFields(value=new Date().toISOString()){const d=new Date(value),t=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');return `<label>Reported date<input id="reported-date" type="date" value="${dayKey(d)}" max="${dayKey()}"></label><div id="reported-time">${timeRow(t).replace(/<button[^>]*class="icon-button remove-time"[^>]*>[\s\S]*?<\/button>/,'')}</div>`}
function readReported(){const row=$('#reported-time .time-row'),time=parseTime(row.querySelector('.time-hour').value,row.querySelector('.time-minute').value,row.querySelector('.time-period')?.value||'24');const d=new Date($('#reported-date').value+'T'+time);if(!Number.isFinite(d.getTime())||d>new Date())return null;return d.toISOString()}
function reportExtra(r){modal('Report an additional action',`<p>Only report an action already taken. This is not a recommendation for an extra dose. For suspected extra doses, contact a pharmacist or clinician.</p>${dateTimeFields()}<button class="primary" id="extra-save">Record separate action</button>`);$('#extra-save').onclick=()=>{const t=readReported();if(!t)return toast('Choose a valid past time.');const d=dayKey(new Date(t)),l=record(state,{key:r.id+'|'+d+'|extra-'+id(),routine:r,date:d,time:'Additional reported action'},'recorded',t);save();$('#modal').close();render();toast('Separate action recorded.',[l.id])}}
function log(o,status='recorded',time){stopRing();const l=record(state,o,status,time);if(l&&time)l.retrospective=true;save();batchSelection.delete(o.key);render();toast(l?(status==='recorded'?'Recorded.':'Skip recorded.'):'This occurrence already has an entry.',l?[l.id]:[])}
async function enable(){state.settings.onboarded=true;state.settings.enabled=true;if(native()&&!QA){if(native().permission()==='default')native().requestPermission();save();setTimeout(render,350)}else{save();render();toast('Phone reminders are available in the Android app.')}}
function downloadCsv(csv,name){if(native()&&!QA){try{native().exportCsv(csv,name);return}catch{}}const a=document.createElement('a'),u=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csvSheet(){const earliest=earliestLogDate(state),today=dayKey();modal('Export history (CSV)',`<p>Download your history as a spreadsheet file, ready to open in Sheets or Excel. ${earliest?`Your history starts ${esc(earliest)}.`:'No history yet.'}</p><label>From<input id="csv-from" type="date" value="${earliest||today}" ${earliest?`min="${earliest}"`:''} max="${today}"></label><label>To<input id="csv-to" type="date" value="${today}" max="${today}"></label><div class="actions"><button type="button" class="primary" id="csv-range">Export selected range</button><button type="button" class="ghost" id="csv-all">Export all data</button></div>`);const run=all=>{const from=$('#csv-from').value||earliest||today,to=$('#csv-to').value||today;const csv=historyCsv(state,all?'':from,all?'':to);downloadCsv(csv,csvFilename(from,to,all));$('#modal').close();toast('History exported as CSV.')};$('#csv-range').onclick=()=>run(false);$('#csv-all').onclick=()=>run(true);}
function bind(){const os=occurrences(state,date),find=k=>os.find(o=>o.key===k);document.querySelectorAll('[data-donate]').forEach(b=>b.addEventListener('click',donate));$('#add')?.addEventListener('click',()=>edit());$('#group-add')?.addEventListener('click',()=>groupEdit());document.querySelectorAll('[data-open]').forEach(c=>{c.onclick=()=>detail(c.dataset.open);c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(c.dataset.open)}}});document.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>log(find(b.dataset.log)));document.querySelectorAll('[data-skip]').forEach(b=>b.onclick=()=>log(find(b.dataset.skip),'skipped'));document.querySelectorAll('[data-snooze]').forEach(b=>b.onclick=()=>{stopRing();state.snoozes[b.dataset.snooze]=Date.now()+state.settings.snooze*60000;save();render();toast(`Snoozed ${state.settings.snooze} minutes. No action recorded.`)});document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{if(c.checked)batchSelection.add(c.dataset.select);else batchSelection.delete(c.dataset.select);render()});document.querySelectorAll('[data-batch]').forEach(b=>b.onclick=()=>{stopRing();const ids=[],batch=id();b.closest('.card').querySelectorAll('[data-select]:checked').forEach(c=>{const l=record(state,find(c.dataset.select),'recorded',undefined,batch);if(l)ids.push(l.id)});batchSelection.clear();save();render();toast(`${ids.length} selected entries recorded.`,ids)});document.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>{undo(state,[b.dataset.undo]);save();render();toast('Entry undone. It no longer counts. No immediate reminder sent.')});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));document.querySelectorAll('[data-routine-delete]').forEach(b=>b.onclick=()=>ask('Delete this routine?','This deletes the routine and its future reminders. Its history stays as a permanent log.',()=>{deleteRoutine(state,b.dataset.routineDelete);save();render();toast('Routine deleted. Its history stays as a permanent log.')}));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>groupEdit(b.dataset.group));document.querySelectorAll('[data-retro]').forEach(b=>b.onclick=()=>{const o=find(b.dataset.retro);modal('Record earlier action',`<p>Scheduled ${esc(o.date)}${o.time!=='untimed'?' · '+esc(fmt(o.time)):''}. This entry will be labeled as entered afterwards.</p>${dateTimeFields(o.time==='untimed'?new Date().toISOString():new Date(o.date+'T'+o.time).toISOString())}<button class="primary" id="retro-save">Save reported action</button>`);$('#retro-save').onclick=()=>{const t=readReported();if(!t)return toast('Choose a valid past time.');$('#modal').close();log(o,'recorded',t)}});document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>{const l=state.logs.find(x=>x.id===b.dataset.correct);modal('Correct reported time',`${dateTimeFields(l.reported)}<p>The old entry remains in the correction trail.</p><button class="primary" id="correct-save">Save correction</button>`);$('#correct-save').onclick=()=>{const t=readReported();if(!t)return toast('Choose a valid past time.');undo(state,[l.id]);record(state,{key:l.key,routine:{id:l.routineId,name:l.name,type:l.type},date:l.date,time:l.scheduled},l.status,t);save();$('#modal').close();render()}});$('#history-filter')?.addEventListener('change',e=>{filter=e.target.value;render()});$('#enable')?.addEventListener('click',enable);$('#disable')?.addEventListener('click',()=>{state.settings.enabled=false;save();render()});document.querySelectorAll('[data-phone]').forEach(b=>b.onclick=()=>native()?.openSettings(b.dataset.phone));document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{state.settings.timeFormat=b.dataset.format;save();render()});document.querySelectorAll('[data-duration]').forEach(b=>b.onclick=()=>{state.settings.snooze=+b.dataset.duration;save();render()});document.querySelectorAll('[data-soundmode]').forEach(b=>b.onclick=()=>{stopPreviewAll();state.settings.soundMode=b.dataset.soundmode;save();render()});$('#tone-list')?.addEventListener('change',e=>{stopPreviewAll();const v=e.target.value;state.settings.toneUri=v;state.settings.toneName=v?(cachedTones||[]).find(t=>t.uri===v)?.name||'':'';state.settings.customTone='';state.settings.customToneName='';save();render()});document.querySelectorAll('[data-preview]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();togglePreview(b.dataset.preview,b.dataset.previewName)}));$('#tones-more')?.addEventListener('click',()=>{tonesExpanded=!tonesExpanded;render()});$('#pick-audio')?.addEventListener('click',()=>{try{if(native()?.pickAudio){native().pickAudio();if(audioPickTimer)clearTimeout(audioPickTimer);audioPickTimer=setTimeout(()=>{audioPickTimer=null;toast('No audio file was picked. Try again with an MP3 from Downloads.');},30000);}}catch{}});$('#copy-upi-settings')?.addEventListener('click',copyUpiId);$('#export-csv')?.addEventListener('click',csvSheet);$('#crash-view')?.addEventListener('click',()=>modal('Problem report',`<p>The most recent time the app stopped. Copy it and share it with the developer if the stopping keeps happening.</p><pre class="crash-body">${esc(lastCrashBody||'No report saved.')}</pre>`));$('#crash-copy')?.addEventListener('click',()=>{if(navigator.clipboard)navigator.clipboard.writeText(lastCrashBody).then(()=>toast('Report copied.')).catch(()=>toast('Copy the report from the View screen.'));else toast('Copy the report from the View screen.')});$('#donate-view')?.addEventListener('click',()=>modal('Donate check','<p>The most recent donate attempt, as recorded on this phone.</p><pre class="crash-body">'+esc(lastDonateBody||'No check saved.')+'</pre>'));$('#donate-copy')?.addEventListener('click',()=>{if(navigator.clipboard)navigator.clipboard.writeText(lastDonateBody).then(()=>toast('Check copied.')).catch(()=>toast('Copy the check from the View screen.'));else toast('Copy the check from the View screen.')});$('#launch-view')?.addEventListener('click',()=>modal('Reminder launch check','<p>The most recent reminder notification, and whether tapping it opened the app and reached the reminder.</p><pre class="crash-body">'+esc(lastLaunchBody||'No check saved.')+'</pre>'));$('#launch-copy')?.addEventListener('click',()=>{if(navigator.clipboard)navigator.clipboard.writeText(lastLaunchBody).then(()=>toast('Check copied.')).catch(()=>toast('Copy the check from the View screen.'));else toast('Copy the check from the View screen.')});$('#zone-confirm')?.addEventListener('click',()=>{state.settings.zone=Intl.DateTimeFormat().resolvedOptions().timeZone;save();render()});$('#delete')?.addEventListener('click',()=>ask('Delete all local records?','This permanently removes your routines, history and reminders on this installation. Export a backup first if needed.',()=>{state=migrate(fresh());save();render()}));$('#export')?.addEventListener('click',()=>{if(native()&&!QA)return native().exportBackup(JSON.stringify(state));const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=u;a.download='remibuds-private-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});$('#restore')?.addEventListener('click',()=>{try{if(native()?.restoreBackup){native().restoreBackup();return}}catch{} $('#import').click()});$('#import')?.addEventListener('change',async e=>{try{const restored=validateBackup(JSON.parse(await e.target.files[0].text()));ask('Restore this backup?','This replaces local records. Reminders will be off until you enable them.',()=>{state=restored;state.settings.enabled=false;save();render();toast('Backup restored. Reminders are off.')})}catch(e){modal('Could not restore backup',`<p>${esc(e&&e.message?e.message:'This file is not a valid Remibuds or Daily Care backup.')}</p><p>Your current records have not changed.</p>`)}});}
function applyCareAuto(k,auto){
 const found=resolveCareAuto(occurrences(state,date),k);
 if(!found){toast('That reminder could not be found, so nothing was recorded.');return;}
 if(found.group){toast('This shared reminder lists each member on the card — mark them there.');return;}
 const o=found.occurrence;
 if(auto==='record')log(o,'recorded');
 else if(auto==='snooze'){stopRing();state.snoozes[o.key]=Date.now()+state.settings.snooze*60000;save();render();toast(`Snoozed ${state.settings.snooze} minutes. No action recorded.`);}
}
window.careOpenNotification=()=>{if(!native()||openingNotification)return;let k='';try{k=native().launchKey()||''}catch{k=''}if(!k)return;const parts=k.split('|');if(parts.length<3)return;let auto='';try{auto=native().launchAuto?native().launchAuto():''}catch{auto=''}if(auto!=='record'&&auto!=='snooze')auto='';openingNotification=true;try{const needRender=date!==parts[1]||page!=='Today';date=parts[1];followingToday=date===dayKey();page='Today';subpage='';pageStack=['Today'];persistPlace();if(needRender)render();const card=[...document.querySelectorAll('[data-occurrence]')].find(c=>c.dataset.occurrence===k);if(card){card.scrollIntoView({block:'center'});card.classList.add('notification-target');const m=card.querySelector('.card-main');if(m)m.focus();if(auto){try{applyCareAuto(k,auto)}catch{}}try{if(native().keyHandled)native().keyHandled()}catch{}}else if(auto){try{if(native().autoHandled)native().autoHandled()}catch{}toast('That reminder could not be found, so nothing was recorded.')}}finally{openingNotification=false}};
window.careResume=()=>{if(followingToday)date=dayKey();if(!QA&&native())native().schedule(JSON.stringify(state));render()};document.addEventListener('visibilitychange',()=>{if(document.hidden){stopPreviewAll();return;}if(!document.hidden)window.careResume()});setInterval(()=>{if(followingToday&&date!==dayKey()){date=dayKey();render()}},30000);window.addEventListener('storage',e=>{if(e.key===STORE&&e.newValue){try{state=migrate(JSON.parse(e.newValue));durableState=JSON.stringify(state);render()}catch{}}});render();save();window.careOpenNotification();

function nudgeWindowLabel(id){return (NUDGE_WINDOWS.find(w=>w.id===id)||NUDGE_WINDOWS[0]).short}
function moreCard(){const n=state.settings.nudges||{enabled:false,texts:[]};const onCount=(n.texts||[]).filter(t=>t.on).length;const streakCount=state.routines.filter(r=>r.type!=='todo'&&!r.archived&&streakInfo(state,r.id).current>0).length;return `<section class="card more-menu"><h2>Streaks &amp; gentle reminders</h2><button class="menu-row" data-subpage="streaks"><span class="menu-icon">${icon('flame')}</span><span class="btn-label"><strong>Streaks</strong><small>${streakCount?`${streakCount} active streak${streakCount>1?'s':''}`:'No streaks yet \u2014 record a routine to start'}</small></span><span class="menu-chev">${icon('right')}</span></button><button class="menu-row" data-subpage="texts"><span class="menu-icon">${icon('edit')}</span><span class="btn-label"><strong>Custom reminder texts</strong><small>${onCount} text${onCount!==1?'s':''} on</small></span><span class="menu-chev">${icon('right')}</span></button><div class="nudge-block"><div><strong>Gentle nudges through the day</strong><small>Rotating wellness reminders, every 30 to 60 minutes. Needs phone reminders on. Early alerts before your own reminders are separate, below.</small></div><div><label>Nudge hours</label><select data-nudge-window-select aria-label="Nudge hours">${NUDGE_WINDOWS.map(w=>`<option value="${w.id}" ${(n.window||'all')===w.id?'selected':''}>${w.label}</option>`).join('')}</select><small>${(n.window||'all')==='all'?'All day means nudges can also arrive at night.':`Nudges arrive only ${nudgeWindowLabel(n.window||'all')}.`}</small></div><label class="switch-row"><span class="switch"><input type="checkbox" data-nudge-toggle ${n.enabled?'checked':''} aria-label="Gentle nudges through the day"><span class="switch-track"><span class="switch-thumb"></span></span></span><span>${n.enabled?'On':'Off'}</span></label><small>${n.enabled?`Nudges arrive only ${nudgeWindowLabel(n.window||'all')}.`:'Turn on to get gentle nudges through the day.'}</small></div></section>`}
function logsPage(){let crash=null,donateDiag=null,launchDiag=null;if(native()&&!QA){try{crash=JSON.parse(native().crashReport()||'{"exists":false}')}catch{crash=null}try{donateDiag=JSON.parse(native().donateReport()||'{"exists":false}')}catch{donateDiag=null}try{launchDiag=JSON.parse(native().launchReport()||'{"exists":false}')}catch{launchDiag=null}}if(crash?.exists)lastCrashBody=crash.body||'';if(donateDiag?.exists)lastDonateBody=JSON.stringify(donateDiag,null,2);if(launchDiag?.exists)lastLaunchBody=JSON.stringify(launchDiag,null,2);return `<button class="link" data-back-more>\u2039 Back to More</button><div class="subpage-head"><h2>Logs &amp; errors</h2></div><p class="empty-copy">Problem reports and checks live here, so they do not pile up in About. Nothing is sent anywhere — these stay on this device.</p>${crash?.exists?`<section class="card"><h2>Last problem report</h2><p>${esc(crash.firstLine||'The app stopped unexpectedly.')}</p><div class="actions"><button class="ghost" id="crash-view">View report</button><button class="ghost" id="crash-copy">Copy report</button></div></section>`:''}${donateDiag?.exists?`<section class="card"><h2>Last donate check</h2><p>${esc(donateDiag.summary||('Payment apps found: '+donateDiag.resolvers))}</p><div class="actions"><button class="ghost" id="donate-view">View check</button><button class="ghost" id="donate-copy">Copy check</button></div></section>`:''}${launchDiag?.exists?`<section class="card"><h2>Last reminder launch</h2><p>${esc(launchLine(launchDiag))}</p>${launchDiag.ringServiceError?`<p>Ring service: ${esc(launchDiag.ringServiceError)}</p>`:''}<div class="actions"><button class="ghost" id="launch-view">View check</button><button class="ghost" id="launch-copy">Copy check</button></div></section>`:''}${!crash?.exists&&!donateDiag?.exists&&!launchDiag?.exists?'<section class="card"><h2>No logs saved yet</h2><p>If the app stops unexpectedly, its report will appear here.</p></section>':''}`;}
function streaksPage(){const rows=state.routines.filter(r=>r.type!=='todo'&&!r.archived).map(r=>{const sk=streakInfo(state,r.id);return `<section class="card care-card type-${esc(r.type)}"><div class="topline"><span class="care-thumb">${icon(r.type)}</span><div><h2>${esc(r.name)}</h2><small>${labels[r.type]||'Medicine'}</small></div><img class="card-art" src="${esc(artSrc(artFor(r)))}" alt="" aria-hidden="true"></div>${sk.current>0?`<div class="streak-row"><span class="streak-pill streak-standout">${icon('flame')}${sk.current}-day streak</span><span class="streak-best">Best: ${sk.best} days</span></div>`:`<p class="count">No streak yet \u2014 record it today to start.${sk.best>0?` Best: ${sk.best} days`:''}</p>`}</section>`}).join('');return `<button class="link" data-back-more>\u2039 Back to More</button><div class="subpage-head"><h2>Streaks</h2></div>${rows||'<p class="empty-copy">No routines with streaks yet. Streaks count consecutive days you record a routine.</p>'}<p class="empty-copy">Streaks do not apply to one-time to-dos.</p>`}
function textsPage(){const n=state.settings.nudges||{enabled:false,texts:[]};const list=(n.texts||[]).map(t=>`<section class="card text-card"><div class="text-row"><div class="text-main"><strong>${esc(t.emoji? t.emoji+' '+t.text : t.text)}</strong>${t.weight>1||t.custom?`<small>${t.weight>1?'More frequent':''}${t.weight>1&&t.custom?' \u00b7 ':''}${t.custom?'Yours':''}</small>`:''}<button class="link danger text-delete" data-text-delete="${esc(t.id)}">Delete</button></div><label class="switch"><input type="checkbox" data-text-toggle="${esc(t.id)}" ${t.on?'checked':''} aria-label="Turn ${esc(t.text)} ${t.on?'off':'on'}"><span class="switch-track"><span class="switch-thumb"></span></span></label></div></section>`).join('');return `<button class="link" data-back-more>\u2039 Back to More</button><div class="subpage-head"><h2>Custom reminder texts</h2><button type="button" class="add-circle-btn" data-text-add-open aria-label="Add reminder text">+</button></div><p class="empty-copy">These rotate one after another every 30 to 60 minutes, in your chosen nudge hours. Phone, office and job reminders appear more often. Turn off any you do not want.</p>${list}`}
function bindMore(){
 document.querySelectorAll('[data-subpage]').forEach(b=>b.addEventListener('click',()=>{subpage=b.dataset.subpage;render();window.scrollTo({top:0})}));
 document.querySelectorAll('[data-back-more]').forEach(b=>b.addEventListener('click',()=>{subpage='';render();window.scrollTo({top:0})}));
 document.querySelectorAll('input[data-nudge-toggle]').forEach(b=>b.addEventListener('change',()=>{const n=state.settings.nudges||(state.settings.nudges={enabled:false,window:'all',texts:NUDGE_DEFAULTS.map(t=>({...t}))});if(!n.window)n.window='all';n.enabled=b.checked;save();render();toast(n.enabled?`Gentle nudges on \u2014 ${nudgeWindowLabel(n.window)}.`:'Gentle nudges off.')}));
 document.querySelectorAll('[data-early-test]').forEach(b=>b.addEventListener('click',()=>{try{if(native()?.testEarlyAlert){if(native().testEarlyAlert())toast('Test notification sent \u2014 check your notifications.');else toast('Notifications are blocked \u2014 allow them in phone settings first.');}else toast('Test notifications work in the Android app.');}catch{toast('Test notifications work in the Android app.');}}));
document.querySelectorAll('input[data-early-toggle]').forEach(b=>b.addEventListener('change',()=>{state.settings.earlyAlerts=b.checked;save();render();toast(b.checked?'Early alerts on \u2014 a quiet notification before each reminder.':'Early alerts off.')}));document.querySelector('[data-nudge-window-select]')?.addEventListener('change',e=>{const n=state.settings.nudges||(state.settings.nudges={enabled:false,window:'all',texts:NUDGE_DEFAULTS.map(t=>({...t}))});n.window=e.target.value;save();render();toast(`Gentle nudges: ${nudgeWindowLabel(n.window)}.`)});document.querySelectorAll('input[data-text-toggle]').forEach(b=>b.addEventListener('change',()=>{const t=(state.settings.nudges?.texts||[]).find(x=>x.id===b.dataset.textToggle);if(t){t.on=b.checked;save();render()}}));
 document.querySelectorAll('[data-text-delete]').forEach(b=>b.addEventListener('click',()=>{const n=state.settings.nudges;if(n)n.texts=n.texts.filter(x=>x.id!==b.dataset.textDelete);save();render()}));
 document.querySelectorAll('[data-text-add-open]').forEach(b=>b.addEventListener('click',()=>{
   modal('Add reminder text',`<form id="text-add-modal-form"><label>Reminder text<input id="text-add-modal-input" name="text" placeholder="e.g. \u{1f9d8} Stretch for a minute" maxlength="120" required></label><p class="fineprint">Type the text as you want it to appear \u2014 emoji included.</p><button class="primary form-submit" type="submit">Add text</button></form>`);
   const f=$('#text-add-modal-form');if(f)f.addEventListener('submit',e=>{e.preventDefault();const text=String($('#text-add-modal-input')?.value||'').trim();if(!text)return;const n=state.settings.nudges||(state.settings.nudges={enabled:false,window:'all',texts:NUDGE_DEFAULTS.map(t=>({...t}))});n.texts.push({id:id(),emoji:'',text,on:true,weight:1,custom:true});$('#modal').close();save();render();toast('Reminder text added.')});
   $('#text-add-modal-input')?.focus();
 }));
}
window.careBackPressed=()=>{try{const d=$('#modal');if(d&&d.open){d.close();return}if(subpage){subpage='';render();return}if(pageStack.length>1){pageStack.pop();page=pageStack[pageStack.length-1];batchSelection.clear();render();window.scrollTo({top:0});return}if(native()?.exitApp)native().exitApp()}catch{}};

function persistPlace(){try{localStorage.setItem(STORE+'-place',JSON.stringify({page,subpage:page==='Settings'?subpage:''}))}catch{}}
